// ByteForge .bfng v1 deterministic reader/generator (Go standard library only).
package main
import("bufio";"encoding/hex";"fmt";"os";"strconv";"strings")
type Edge struct{ctx []int; next int; count int}
func fail(s string){fmt.Fprintln(os.Stderr,"byteforge:",s);os.Exit(1)}
func main(){if len(os.Args)<2||len(os.Args)>3{fail("usage: byteforge model.bfng [token-count]")};f,e:=os.Open(os.Args[1]);if e!=nil{fail("cannot open model")};defer f.Close();sc:=bufio.NewScanner(f);sc.Buffer(make([]byte,4096),1<<20);if !sc.Scan(){fail("empty model")};h:=strings.Split(sc.Text(),"\t");if len(h)!=4||h[0]!="BYTEFORGE_NGRAM_V1"{fail("bad model header")};order,_:=strconv.Atoi(h[1]);vn,_:=strconv.Atoi(h[2]);bos,_:=strconv.Atoi(h[3]);if order<1||order>8||vn<1||vn>20000||bos!=vn{fail("invalid model header")};v:=make([]string,vn);edges:=[]Edge{};for sc.Scan(){p:=strings.Split(sc.Text(),"\t");if len(p)==3&&p[0]=="v"{id,_:=strconv.Atoi(p[1]);b,err:=hex.DecodeString(p[2]);if err!=nil||id<0||id>=vn{fail("invalid vocabulary")};v[id]=string(b)}else if len(p)==order+3&&p[0]=="n"{c:=make([]int,order);ok:=true;for i:=range c{c[i],e=strconv.Atoi(p[i+1]);if e!=nil||c[i]<0||c[i]>bos{ok=false}};n,_:=strconv.Atoi(p[order+1]);cnt,_:=strconv.Atoi(p[order+2]);if !ok||n<0||n>=vn||cnt<=0{fail("invalid transition")};edges=append(edges,Edge{c,n,cnt})}else{fail("unknown record")}};if sc.Err()!=nil{fail("model read error")};for _,t:=range v{if t==""{fail("missing vocabulary token")}};steps:=20;if len(os.Args)==3{steps,e=strconv.Atoi(os.Args[2]);if e!=nil||steps<0||steps>10000{fail("bad token count")}};ctx:=make([]int,order);for i:=range ctx{ctx[i]=bos};out:=[]string{};for k:=0;k<steps;k++{best:=-1;for i,x:=range edges{same:=true;for j:=range ctx{if x.ctx[j]!=ctx[j]{same=false;break}};if same&&(best<0||x.count>edges[best].count||(x.count==edges[best].count&&x.next<edges[best].next)){best=i}};if best<0{break};if v[edges[best].next]=="__BYTEFORGE_EOS__"{break};out=append(out,v[edges[best].next]);copy(ctx,ctx[1:]);ctx[order-1]=edges[best].next};fmt.Println(strings.Join(out," "))}
